	allegiance = "Royaume de Stormwind · Armée de Stormwind",
	aliases = { "Marris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maréchal Marris commande les soldats de {link:lakeshire}Lakeshire{/link}. Il a perdu la bataille du {link:stonewatch-keep}Donjon de Guet-de-pierre{/link}, et il doit maintenant tenir la ville avec le peu qui reste. C'est un soldat pragmatique. Il sait que la bravoure seule ne gagnera pas cette guerre, et il compte ses ennemis aux haches, aux orbes et aux têtes qu'on lui rapporte.]=],
		},
		{
			title = "Importance",
			text = [=[Marris est l'épée de {link:lakeshire}Lakeshire{/link}, comme {link:magistrate-solomon}Solomon{/link} en est la voix. Pendant que le magistrat écrit des lettres, le maréchal mène la guerre que personne d'autre ne veut mener, contre un ennemi qui le surpasse en nombre dans chaque vallée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tient {link:lakeshire}Lakeshire{/link} contre les {link:blackrock-mountain}Blackrock{/link} avec une petite garnison.
• Il traque les coureurs Blackrock qui tendent des embuscades sur la route de {link:stonewatch-keep}Guet-de-pierre{/link}.
• Il détruit les orbes ténébreux des lanceurs d'ombre Blackrock.
• Il mène une guerre de famine contre les camps orcs.]=],
		},
	},
	chapters = {
		{
			title = "La menace Blackrock",
			hint = "Aidez le maréchal à éclaircir les rangs des Blackrock.",
			text = [=[Les orcs vinrent des {link:burning-steppes}Steppes ardentes{/link}, prirent le donjon et enfermèrent le peuple de {link:lakeshire}Lakeshire{/link} dans sa propre ville. Marris demanda leurs haches pour preuve, puis la tête de {link:tharil-zun}Tharil'zun{/link}, l'{link:orcs}orc{/link} rusé qui menait les embuscades sur la route de {link:stonewatch-keep}Guet-de-pierre{/link}.]=],
		},
		{
			title = "La magie de l'ombre",
			hint = [=[Apportez au maréchal les orbes ténébreux des lanceurs de sorts Blackrock.]=],
			text = [=[Les {link:blackrock-mountain}Blackrock{/link} avaient amené des lanceurs d'ombre, et avec eux vinrent des orbes de minuit, souillés par les démons. Ces orbes avaient abattu bien des défenseurs des {link:redridge-mountains}Carmines{/link}. Marris refusa de les garder. Il les fit tous emporter pour qu'ils soient détruits.]=],
		},
		{
			title = "Porté disparu",
			hint = "Ramenez chez lui le soldat perdu à Guet-de-pierre.",
			text = [=[Le caporal {link:corporal-keeshan}Keeshan{/link} revint du {link:render-s-camp}Rocher des Etripeurs{/link}, blessé et seul. La plupart des hommes de son régiment étaient morts autour de lui. Marris y vit tout de même une victoire, et il récompensa ceux qui avaient ramené le soldat.]=],
		},
	},
	mentions = {
		{ text = "Le blocus {link:blackrock-mountain}Blackrock{/link}" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "gouverne la ville qu'il garde" },
		{ id = "corporal-keeshan", name = "Caporal Keeshan", note = "son soldat perdu" },
		{ id = "tharil-zun", name = "Tharil'zun", note = "l'orc dont il voulait la mort" },
		{ id = "bellygrub", name = "Bellygrub", note = "nommé par lui" },
	},
})

