Translate("frFR", "morganth", {
	title = "Morganth",
	subtitle = "Démoniste de la Tour d'Ilgalar",
	found = "Le sommet de la Tour d'Ilgalar",
	hint = [=[Montez au sommet de la Tour d'Ilgalar et affrontez son maître.]=],
	allegiance = "Lui-même · les gnolls Sombrepoil",
	sections = {
		{
			title = "Résumé",
			text = [=[Morganth est un démoniste humain qui demeure dans la {link:tower-of-ilgalar}Tour d'Ilgalar{/link}. Il y a longtemps, il étudia dans la tour des mages de {link:stormwind-city}Stormwind{/link}, l'un des trois qui y apprirent ensemble. Il tomba dans les arts sombres, et comme il refusait de s'en détourner, il fut banni. Il emporta avec lui un livre scellé de magie de l'ombre. À présent, il commande les {link:shadowhide-gnolls}gnolls Sombrepoil{/link}, leur parle par des pendentifs enchantés et invoque des démons à ses côtés.]=],
		},
		{
			title = "Importance",
			text = [=[Morganth est l'auteur caché de la ruine des {link:redridge-mountains}Carmines{/link}. C'est sa magie qui nourrit la sauvagerie des {link:blackrock-mountain}Blackrock{/link} au {link:stonewatch-keep}Donjon de Guet-de-pierre{/link}. Il est aussi le rival du grand mage {link:theocritus}Theocritus{/link}, qui l'observe depuis {link:elwynn-forest}Elwynn{/link} depuis longtemps.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il s'allia à {link:gath-ilzogg}Gath'Ilzogg{/link} et au {link:blackrock-clan}clan Blackrock{/link}, et les aida à prendre le {link:stonewatch-keep}Donjon de Guet-de-pierre{/link}.
• Il se retourna contre les orcs peu après, éleva sa propre tour et lia les {link:shadowhide-gnolls}gnolls Sombrepoil{/link} à son service.
• Il garde le Traité d'Ur sur la Magie des Ombres, bien qu'il n'ait jamais brisé les sceaux que les mages de {link:stormwind-city}Stormwind{/link} y avaient apposés.
• Il cherche la {red:scythe-of-elune}Faux d'Élune{/red}.]=],
		},
	},
	chapters = {
		{
			title = "L'alliance brisée",
			hint = "Aidez Theocritus à sonder le donjon des orcs.",
			text = [=[L'Œil d'{link:tower-of-azora}Azora{/link} montra à {link:theocritus}Theocritus{/link} un démoniste en guerre contre les orcs qu'il avait jadis aidés. Pourquoi les deux s'étaient brouillés, même le magistrat {link:magistrate-solomon}Solomon{/link} n'aurait su le dire. Pour en apprendre davantage, le grand mage cacha un glyphe au sommet de la tour de guet voisine du {link:stonewatch-keep}Donjon de Guet-de-pierre{/link}, et il commença à lire l'esprit des orcs qui s'y trouvaient.]=],
		},
		{
			title = "La Faux",
			hint = "Faites ce que Theocritus n'est pas prêt à faire lui-même.",
			text = [=[{link:theocritus}Theocritus{/link} apprit enfin ce que cherchait Morganth : la Faux d'Élune. Il craignait que le démoniste ne l'ait déjà trouvée, et que {link:stormwind-city}Stormwind{/link} ne sente bientôt sa puissance. Le grand mage refusa d'affronter Morganth lui-même, alors un autre gravit la {link:tower-of-ilgalar}Tour d'Ilgalar{/link} à sa place. Le pendentif de l'ombre de Morganth revint en {link:elwynn-forest}Elwynn{/link}, et Theocritus déclara le royaume sauvé d'un grave péril.]=],
		},
	},
	mentions = {
		{ text = "La loi de {link:magistrate-solomon}Solomon{/link}" },
		{ text = "La récupération de {link:theocritus}Theocritus{/link}" },
		{ text = "Un œil vigilant" },
		{ text = "Traité d'Ur sur la Magie des Ombres" },
	},
	bonds = {
		{ id = "theocritus", name = "Theocritus", note = "son rival" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "son ancien allié" },
		{ id = "lieutenant-fangore", name = "Lieutenant Fangore", note = "son lieutenant gnoll" },
		{ id = "shadowhide-gnolls", name = "Gnolls Sombrepoil", note = "ses serviteurs" },
	},
})

