Translate("frFR", "blackrock-clan", {
	title = "Clan Blackrock",
	aliases = { "clan Blackrock", "orcs Blackrock" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les {link:blackrock-mountain}Blackrock{/link} sont l'un des clans les plus anciens et les plus belliqueux des {link:orcs}orcs{/link}. Ils furent l'épine dorsale de l'ancienne {link:horde}Horde{/link} et lui donnèrent deux de ses chefs de guerre. Longtemps après la défaite de la Horde, les Blackrock ont gardé les anciennes coutumes de la guerre, et ils n'ont jamais fait la paix avec les humains.]=],
		},
		{
			title = "Histoire",
			text = [=[Lors de la {link:first-war}Première Guerre{/link}, le chef Blackrock Blackhand mena la {link:horde}Horde{/link} en tant que chef de guerre, bien que d'autres tirassent les ficelles derrière lui. Il fut tué par l'un des siens, {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, un guerrier Blackrock qui mena ensuite la Horde à la conquête de {link:stormwind-city}Stormwind{/link}. Lors de la {link:second-war}Deuxième Guerre{/link}, la Horde de Doomhammer fut brisée au {link:blackrock-mountain}mont Blackrock{/link} après qu'il eut tué {link:anduin-lothar}Anduin Lothar{/link}. La plupart des orcs furent parqués dans des camps. Les Blackrock qui s'échappèrent se réfugièrent dans la montagne qui porte leur nom, et ils en tiennent les hauteurs depuis.]=],
		},
		{
			title = "Dans les Carmines",
			text = [=[À présent, les {link:blackrock-mountain}Blackrock{/link} sont descendus vers le sud depuis les {link:burning-steppes}Steppes ardentes{/link}. Sous les ordres du seigneur de guerre {link:gath-ilzogg}Gath'Ilzogg{/link}, et avec la magie noire de {link:morganth}Morganth{/link}, ils prirent le {link:stonewatch-keep}Donjon de Guet-de-pierre{/link} et abattirent le pont du {link:lake-everstill}Lac placide{/link}. Leurs coureurs tendent des embuscades sur les routes, leurs lanceurs d'ombre portent des orbes souillés par les démons, et leurs champions campent près du col du nord. Une autre bande de guerre est entrée à l'extrême sud-est par {link:stranglethorn-vale}la Vallée{/link} des Etripeurs. Pourtant, ils se sont avancés si loin dans le royaume qu'ils doivent fourrager dans les collines pour trouver vivres et armes, et {link:lakeshire}Lakeshire{/link} espère les réduire par la faim.]=],
		},
		{
			title = "La nouvelle Horde",
			text = [=[Tous les {link:blackrock-mountain}Blackrock{/link} ne restèrent pas avec le clan. {link:eitrigg}Eitrigg{/link}, qui servit autrefois le chef de guerre Blackrock, en vint à haïr les adorateurs de démons qui égarèrent son peuple. Il sert désormais {link:thrall}Thrall{/link} à {link:orgrimmar}Orgrimmar{/link}, loin de la montagne de son ancien clan.]=],
		},
	},
})

Translate("frFR", "shadowhide-gnolls", {
	title = "Gnolls Sombrepoil",
	aliases = { "gnolls Sombrepoil", "Sombrepoil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Sombrepoil sont un clan de {link:gnolls}gnolls{/link} qui vit dans {link:stranglethorn-vale}la Vallée{/link} de {link:galardell-valley}Galardell{/link}, au nord-est des {link:redridge-mountains}Carmines{/link}. Ils servent le démoniste {link:morganth}Morganth{/link}. Leur chef est le lieutenant {link:lieutenant-fangore}Fangore{/link}. Leurs tisseurs de ténèbres pratiquent une magie ombreuse, leurs assassins frappent sans être vus, et leurs tueurs attaquent orcs et humains sans distinction.]=],
		},
		{
			title = "Liés par les pendentifs",
			text = [=[Chaque Sombrepoil porte un pendentif par lequel {link:morganth}Morganth{/link} lui parle. Le grand mage {link:theocritus}Theocritus{/link} a passé des mois à tenter de pénétrer ces pendentifs. Il a réussi à envoyer un message à travers certains d'entre eux, et il espère un jour y envoyer une attaque qui figerait chaque {link:gnolls}gnoll{/link} qui en porte un.]=],
		},
		{
			title = "Devant la loi",
			text = [=[La cour de {link:lakeshire}Lakeshire{/link} déclara les Sombrepoil coupables d'avoir aidé un criminel du royaume, un crime puni de mort. L'huissier {link:bailiff-conacher}Conacher{/link} paie pour leurs pendentifs en guise de preuve, et le magistrat a mis à prix la tête de {link:lieutenant-fangore}Fangore{/link} lui-même.]=],
		},
		{
			title = "Ennemis de tous",
			text = [=[Les Sombrepoil ne sont pas des amis des {link:blackrock-mountain}Blackrock{/link}. Quand {link:morganth}Morganth{/link} se retourna contre ses alliés orcs, ses gnolls se retournèrent avec lui, et des orcs sont morts de leurs mains aussi sûrement que des hommes.]=],
		},
	},
})

Translate("frFR", "redridge-gnolls", {
	title = "Gnolls des Carmines",
	aliases = { "gnolls des Carmines", "meute des Carmines" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les gnolls des Carmines sont l'ancienne meute de gnolls des Carmines, distincte des {link:shadowhide-gnolls}Sombrepoil{/link} qui servent {link:morganth}Morganth{/link}. Ils ne servent ni démoniste ni {link:orcs}orc{/link}. Leurs brutes et leurs mystiques parcourent les collines au nord de {link:lakeshire}Lakeshire{/link}, et leurs braconniers et leurs bâtards campent le long de la route du sud. Leur chef est {link:yowler}Yowler{/link}, qui a son antre dans les {link:redridge-canyons}Canyons des Carmines{/link}, et dont le hurlement porte jusqu'à Lakeshire.]=],
		},
		{
			title = "Leurs mœurs",
			text = [=[Les gnolls des Carmines prennent ce que la guerre laisse sans garde. Ils s'emparèrent du convoi qui transportait le fer destiné au pont du {link:lake-everstill}Lac placide{/link}. Ils volent des chevaux à l'écurie de {link:lakeshire}Lakeshire{/link}. Ils se sont installés dans les {link:rethban-caverns}Cavernes de Rethban{/link}, où leurs trimeurs extraient le minerai que la ville exploitait autrefois. Ils sont peu organisés, mais ils respectent la force par-dessus tout. L'adjoint {link:deputy-feldon}Feldon{/link} espère que la mort de leurs cogneurs les plus féroces apprendra aux autres à rester dans les collines. À Rethban, un {link:gnolls}gnoll{/link} nommé Ardo Dirtpaw mène la meute qui tient les cavernes.]=],
		},
	},
})
